def chunk_text(text, max_words):
    words = text.split()
    if not words or max_words <= 0:
        return []
    chunks = []
    for i in range(0, len(words), max_words):
        chunks.append(' '.join(words[i:i + max_words]))
    return chunks

def score_relevance(chunk, query):
    chunk_words = set(chunk.lower().split())
    query_words = set(query.lower().split())
    return len(chunk_words & query_words)

def retrieve_top_k(chunks, query, k):
    scored = [(chunk, score_relevance(chunk, query)) for chunk in chunks]
    scored.sort(key=lambda x: x[1], reverse=True)
    return [chunk for chunk, _ in scored[:k]]

def build_prompt(question, chunks):
    context = '\n'.join(f'- {chunk}' for chunk in chunks)
    return f'Context:\n{context}\n\nQuestion: {question}'

def format_citation(source, idx):
    return f'[{idx}] {source}'
